  A('div',{key:'pool',style:{position:'absolute',left:0,right:0,top:px(horizonY-h*0.10),height:px(h*0.30),
     background:'radial-gradient(60% 70% at 50% 60%, '+D.cyan+'12 0%, transparent 70%)'}}));
// grounded(cxScreen, baseY, wd, key): a hard CONTACT shadow ellipse so an object reads as sitting ON the desk.
const grounded = (cxp, baseY, wd, key)=> A('div',{key:key,style:{position:'absolute',left:px(cxp-wd/2),top:px(baseY-wd*0.07),
   width:px(wd),height:px(wd*0.15),borderRadius:'50%',pointerEvents:'none',zIndex:0,
   background:'radial-gradient(ellipse at center, rgba(0,0,0,0.60) 0%, rgba(0,0,0,0.25) 45%, transparent 72%)'}});
// onDesk(node, tiltDeg, key): wrap an object in a slight perspective tilt so it sits in the world (GPU-cheap).
const onDesk = (node, tiltX, tiltY, key)=> A('div',{key:key,style:{transformStyle:'preserve-3d',
   transform:'perspective('+px(w*0.9)+'px) rotateX('+tiltX+'deg) rotateY('+tiltY+'deg)'}}, node);

// amber answer TILE centre (the Pro/Price cell ≈ row1,col2 of a 4×4 grid over the page)
const TC=4, TR=4, tw=pgW/TC, th=pgH/TR;
const amTX = pageLeft + 2.5*tw, amTY = pageTop + 1.5*th;
// ORBIT camera (fake 3D: perspective + slight rotateY + a circular translate) — the hero move
const orbit = (prog, node) => A('div',{key:'orb',style:{position:'absolute',inset:0,
   transform:'perspective('+px(w*1.4)+'px) translateX('+px(Math.sin(prog*Math.PI*0.6)*w*0.022)+'px) rotateY('+interpolate(prog,[0,1],[-5,5])+'deg) scale('+(1+0.04*prog)+')',
   transformOrigin:((amTX/w)*100)+'% '+((amTY/h)*100)+'%'}}, node);
// the cyan TILE-GRID over the page — tiles stay in their layout positions, lift + shimmer; the amber tile glows
const mkTiles = (startF) => {
  const tiles=[];
  for(let r=0;r<TR;r++) for(let c=0;c<TC;c++){
    const i=r*TC+c;
    const ts = spring({frame:F-(startF+i*2), fps, config:SPR.glide});
    const op = interpolate(ts,[0,1],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});
    const isAmber = (r===1 && c===2);
    const shimmer = 0.5 + 0.5*Math.abs(Math.sin(F*0.06 + i));
    tiles.push(A('div',{key:'t'+i,style:{position:'absolute',left:px(pageLeft+c*tw),top:px(pageTop+r*th),width:px(tw),height:px(th),
       boxSizing:'border-box',border:'1.5px solid '+(isAmber?D.amber:D.cyan),
       background:isAmber?'rgba(251,191,36,0.18)':'rgba(34,211,238,0.06)',
       opacity:op*(isAmber?1:0.45+0.2*shimmer),transform:'translateY('+px(interpolate(ts,[0,1],[h*0.012,0]))+'px) scale('+interpolate(ts,[0,1],[0.92,1])+')'}}));
  }
  return A('div',{key:'tiles',style:{position:'absolute',inset:0}}, ...tiles);
};
// the page protagonist (kept whole — the lens reads it; tiles overlay it)
const heroPage = A('div',{key:'hp',style:{position:'absolute',left:px(pageLeft),top:px(pageTop),width:pgW,
   transform:'scale('+breathe(0.007,0.05)+')',transformOrigin:'center'}}, cardShadow, mkCard({}));
const s6Title = A('div',{key:'tl',style:{position:'absolute',left:px(w*0.06),top:px(h*0.08),zIndex:9}},
   T('sub','Read the Picture',{}), T('body','what if it just… looked?',{w:500,color:D.violet,css:{marginTop:px(h*0.012)}}));

const p = interpolate(F,[0,dur],[0,1],{extrapolateRight:'clamp'});
const dockF = (findWord('just looked at') ?? Math.round(dur*0.30));
const dock = spring({frame:F-dockF, fps, config:SPR.settle});      // lens docks to the amber (weight 0.4, spring 0.6)
const lCX = interpolate(dock,[0,1],[amTX+w*0.10, amTX]), lCY = interpolate(dock,[0,1],[amTY-h*0.05, amTY]);
const lens = realLens(mkCard({}), pgW*0.625, pgH*0.375, lCX, lCY, px(w*0.13), 1.5, 1, 'lens');
const swell = interpolate(F,[dockF+3, dockF+30],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});  // bloom swell (lag 3f)
const amberPulse = 0.6 + 0.25*Math.abs(Math.sin(F*0.06));          // amberCell breathe
const close = A('div',{key:'cl',style:{position:'absolute',left:0,right:0,top:px(h*0.82),textAlign:'center',
   opacity:interpolate(F,[dockF+10, dockF+24],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'}),fontFamily:D.font_display}},
   A('span',{key:'a',style:{fontWeight:500,fontSize:px(TYPE.title),color:D.text_dim}},'it just… '),
   A('span',{key:'b',style:{fontWeight:800,fontSize:px(TYPE.sub),color:D.violet,letterSpacing:'0.02em'}},'LOOKED.'));
// final push-in (camera) layered on the orbit, toward the amber
return orbit(Math.min(1,p*1.1), A(AbsoluteFill,{}, mkBackdrop(p),
   heroPage, mkTiles(0),
   bloom(D.amber, amTX, amTY, w*0.20, (swell*amberPulse)*0.85, 'ab'),  // 3-layer bloom (glow material)
   lens, close, s6Title));
